window.PM_RUNAS_X2 = {"Fehu": {"c": "Haz un presupuesto simple esta semana y decide a qué dedicarás tu energía y tu dinero.", "q": "¿Estoy invirtiendo mi energía en lo que realmente quiero ver crecer?", "af": "Valoro lo que tengo y lo cuido para que crezca.", "p": "antes recibiste o perdiste recursos que hoy condicionan tu relación con el dinero y la seguridad", "f": "se acerca una etapa donde lo que cuides hoy se multiplica", "ic": "Antes de gastar o prometer, haz inventario de lo que ya tienes."}, "Uruz": {"c": "Ponte un reto físico o práctico a tu medida y cúmplelo durante siete días.", "q": "¿Qué reto me da miedo y, a la vez, me hace sentir vivo?", "af": "Tengo la fuerza necesaria para lo que viene.", "p": "atravesaste una prueba que te fortaleció, aunque entonces no lo viste así", "f": "vendrá un momento que pide valentía y salud: cuídate desde ahora", "ic": "Prioriza descanso, comida y movimiento antes de lanzarte a nada nuevo."}, "Thurisaz": {"c": "Antes de reaccionar, espera veinticuatro horas y escribe qué quieres proteger realmente.", "q": "¿Qué límite necesito poner sin dañar a nadie?", "af": "Pongo límites con firmeza y con calma.", "p": "una confrontación o un obstáculo marcó tu manera de defenderte hoy", "f": "pronto podrías toparte con una barrera: mira de qué te protege antes de embestirla", "ic": "Cuenta hasta diez; el impulso que te empuja hoy puede no ser tu mejor consejero."}, "Ansuz": {"c": "Busca hoy esa conversación pendiente o pide consejo a alguien que admires.", "q": "¿Qué mensaje estoy evitando decir o escuchar?", "af": "Escucho con atención y hablo con verdad.", "p": "recibiste palabras o un consejo que sigue resonando en ti", "f": "llegará una noticia, una idea o una conversación clave; mantente atento", "ic": "Revisa los hechos antes de creer un mensaje; pide que te lo repitan si hay dudas."}, "Raidho": {"c": "Planea el siguiente paso de tu camino y ponle fecha en el calendario.", "q": "¿Voy en la dirección que realmente elegí?", "af": "Avanzo a mi ritmo y con rumbo claro.", "p": "un viaje o un cambio de rumbo te trajo hasta aquí", "f": "se abre un movimiento: un viaje, una mudanza o un nuevo rumbo", "ic": "Antes de seguir, revisa el mapa: ¿sigue siendo tu destino el mismo?"}, "Kenaz": {"c": "Dedica treinta minutos a algo creativo sin buscar que salga perfecto.", "q": "¿Qué idea quiere ser encendida ahora?", "af": "Mi creatividad ilumina mi camino.", "p": "una chispa creativa o un conocimiento te abrió puertas", "f": "viene claridad e inspiración: prepara un cuaderno", "ic": "Busca una fuente nueva de inspiración: un lugar, una persona, un libro."}, "Gebo": {"c": "Haz hoy un gesto generoso sin esperar nada a cambio y observa cómo te sientes.", "q": "¿Doy y recibo en equilibrio en mis relaciones?", "af": "Doy y recibo con gratitud.", "p": "un intercambio o un regalo marcó una relación importante", "f": "una alianza o un acuerdo justo se aproxima", "ic": "Revisa si estás dando de más o recibiendo de menos; reequilibra con una charla."}, "Wunjo": {"c": "Comparte hoy una buena noticia y celébrala con alguien cercano.", "q": "¿Qué me haría sentir en paz y alegría genuina esta semana?", "af": "Me permito sentir alegría sin culpa.", "p": "una época de bienestar te dejó una huella luminosa", "f": "se acerca un tiempo de armonía y reconocimiento", "ic": "No fuerces la alegría: empieza por lo básico (sueño, comida, compañía)."}, "Hagalaz": {"c": "Acepta lo que no puedes controlar y concéntrate en reconstruir lo que sí.", "q": "¿Qué necesita romperse para que algo mejor pueda nacer?", "af": "Después de la tormenta, reconstruyo con más sabiduría.", "p": "una sacudida te obligó a cambiar de rumbo y ya pasó", "f": "podría llegar un cambio inesperado: cuida lo esencial y mantén la calma", "ic": "Evita decisiones grandes mientras dure la sacudida; asegura primero lo básico."}, "Nauthiz": {"c": "Identifica una necesidad real que has pospuesto y atiéndela con un pequeño paso.", "q": "¿Qué necesito de verdad, más allá de lo que quiero?", "af": "Con paciencia, supero cada limitación.", "p": "pasaste por escasez y aprendiste a administrar lo que tenías", "f": "viene un periodo de ajuste: planifica y prioriza", "ic": "Pospón gastos o compromisos no urgentes y cuida tu energía."}, "Isa": {"c": "Aprovecha la pausa: descansa, reflexiona y no tomes decisiones apresuradas.", "q": "¿Qué emoción tengo congelada y necesito mirar con calma?", "af": "Acepto la pausa como parte del proceso.", "p": "una etapa de estancamiento te enseñó a esperar", "f": "habrá un tiempo de espera; no es retroceso, es preparación", "ic": "No presiones ni ultimátums: da tiempo y espacio."}, "Jera": {"c": "Reconoce y celebra un resultado que tu constancia ya produjo.", "q": "¿Qué sembré hace tiempo que ya está dando fruto?", "af": "Cosecho lo que sembré con paciencia.", "p": "el esfuerzo de otro tiempo hoy te sostiene", "f": "vienen resultados a mediano plazo si sigues constante", "ic": "Paciencia: lo bueno madura en su ciclo, no en el tuyo."}, "Eihwaz": {"c": "Fortalece tu base: hábitos, rutina, apoyos; algo que te sostenga en la tormenta.", "q": "¿Qué me mantiene firme cuando todo cambia?", "af": "Estoy firme y flexible como un tejo.", "p": "una prueba de resistencia te enseñó a sostenerte", "f": "vendrá un periodo de transición donde tu constancia será clave", "ic": "Evita rutas cortas; elige lo que dura aunque sea más lento."}, "Perthro": {"c": "Deja que algo se revele sin forzarlo; anota señales y coincidencias durante una semana.", "q": "¿Qué parte de mi destino prefiero no mirar todavía?", "af": "Confío en lo que se revela a su tiempo.", "p": "algo oculto se aclaró y cambió tu mirada", "f": "se revelará algo hoy escondido; mantén la mente abierta", "ic": "No tomes por cierto lo que aún no está claro; espera más información."}, "Algiz": {"c": "Rodéate de personas y lugares que te cuiden; cuida también tus límites.", "q": "¿Qué o quién me protege, y qué necesito proteger yo?", "af": "Estoy protegido y aprendo a protegerme.", "p": "alguien o algo te protegió cuando más lo necesitabas", "f": "viene una etapa de resguardo y de aliados confiables", "ic": "Cuídate de exponerte demasiado; elige bien en quién confías."}, "Sowilo": {"c": "Muéstrate: comparte un logro, ocupa tu lugar con confianza.", "q": "¿Dónde estoy ocultando mi luz?", "af": "Mi luz brilla sin pedir permiso.", "p": "una victoria o un éxito sigue dándote energía", "f": "se acerca un momento de éxito y claridad: aprovéchalo", "ic": "No te quemes: el exceso de entusiasmo también cansa; dosifica."}, "Tiwaz": {"c": "Actúa con honor: cumple una promesa pendiente o defiende lo que es justo.", "q": "¿Por qué causa vale la pena esforzarme y arriesgar?", "af": "Actúo con coraje y justicia.", "p": "un acto de valentía o un conflicto justo te definió", "f": "viene un momento de lucha noble o de decisión firme", "ic": "Cuida que el coraje no se vuelva obstinación; confirma que tu causa es justa."}, "Berkano": {"c": "Cuida algo que apenas nace: un proyecto, un hábito, una relación.", "q": "¿Qué nuevo comienzo merece mi cuidado ahora?", "af": "Nutro lo nuevo con ternura y constancia.", "p": "algo nació en tu vida y todavía te marca", "f": "habrá un nuevo comienzo, un nacimiento o una renovación", "ic": "No exijas resultados a lo que apenas nace; falta tiempo y cuidado."}, "Ehwaz": {"c": "Fortalece una alianza de confianza: pide ayuda o ayuda tú a alguien.", "q": "¿Con quién avanzo mejor y cómo puedo cuidar ese vínculo?", "af": "Avanzo en confianza y compañía.", "p": "un compañero de camino te impulsó cuando lo necesitabas", "f": "llega un avance gradual, a menudo acompañado de alguien de confianza", "ic": "Si algo no avanza, revisa la comunicación con quien te acompaña."}, "Mannaz": {"c": "Mírate con honestidad: ¿cómo te ven los demás y cómo te ves tú?", "q": "¿Qué papel represento en mi grupo y es el que quiero?", "af": "Soy parte de algo y soy yo mismo.", "p": "tus relaciones moldearon tu identidad", "f": "es tiempo de cooperar y de mirarte con claridad", "ic": "Evita compararte; tu valor no depende del papel que otros te den."}, "Laguz": {"c": "Escucha tu intuición: lleva un diario de sueños o de corazonadas esta semana.", "q": "¿Qué me dice mi intuición que mi mente aún discute?", "af": "Confío en mi intuición y fluyo.", "p": "una emoción profunda o una intuición te guió", "f": "crece la sensibilidad y la intuición: cuida tu descanso", "ic": "Cuida que la emoción no te arrastre: respira antes de decidir."}, "Ingwaz": {"c": "Termina una tarea pendiente: esa semilla ya está lista para dar frutos.", "q": "¿Qué proceso estoy a punto de completar?", "af": "Cierro ciclos con calma y gratitud.", "p": "una etapa se completó y dejó algo en ti", "f": "se acerca el cierre de un ciclo y la preparación de otro", "ic": "No abras nuevos frentes hasta cerrar el actual."}, "Dagaz": {"c": "Elige un cambio positivo y hazlo hoy: el momento de la claridad es ahora.", "q": "¿Qué parte de mi vida está lista para amanecer?", "af": "Despierto a una nueva etapa con esperanza.", "p": "una transformación te cambió para bien", "f": "viene un cambio luminoso, un antes y un después", "ic": "No te quedes en la espera; el cambio llega cuando actúas."}, "Othala": {"c": "Honra tus raíces: llama a un familiar o ordena algo de tu hogar.", "q": "¿Qué heredé que quiero conservar y qué quiero dejar atrás?", "af": "Honro mis raíces y construyo mi hogar.", "p": "tu familia o tu hogar fue base de lo que eres hoy", "f": "es tiempo de afianzar el hogar, la familia o el patrimonio", "ic": "No te aferres a lo heredado si ya no te sirve; elige qué conservas."}};
window.PM_ICHING_X2 = {"1": {"k": "la fuerza creativa", "c": "Actúa con constancia y rectitud, sin imponerte.", "q": "¿Qué quiero iniciar con todo mi compromiso?"}, "2": {"k": "la receptividad", "c": "Apoya, sigue y deja que las cosas maduren.", "q": "¿Qué gano si dejo de querer dirigirlo todo?"}, "3": {"k": "los comienzos difíciles", "c": "Ordena paso a paso y pide ayuda.", "q": "¿Qué primer paso pequeño puedo dar hoy?"}, "4": {"k": "el aprendizaje", "c": "Pregunta con humildad y escucha una vez.", "q": "¿Qué me falta aprender para decidir bien?"}, "5": {"k": "la espera paciente", "c": "Aliméntate, prepárate y no fuerces el momento.", "q": "¿Cómo puedo usar esta espera a mi favor?"}, "6": {"k": "el conflicto", "c": "Busca un acuerdo y evita llevarlo al extremo.", "q": "¿Qué gano realmente ganando esta discusión?"}, "7": {"k": "la disciplina colectiva", "c": "Organiza el esfuerzo con un objetivo claro.", "q": "¿Tengo claro por qué estoy luchando?"}, "8": {"k": "la unión sincera", "c": "Únete pronto a quienes comparten tu rumbo.", "q": "¿Con quién estoy dispuesto a comprometerme de verdad?"}, "9": {"k": "los pequeños frenos", "c": "Insiste con suavidad; las gotas llenan el vaso.", "q": "¿Qué detalle pequeño me está frenando?"}, "10": {"k": "la conducta prudente", "c": "Avanza con cortesía, incluso ante lo difícil.", "q": "¿Cómo puedo ser firme sin ser brusco?"}, "11": {"k": "la paz y la prosperidad", "c": "Aprovecha la armonía para construir y compartir.", "q": "¿Qué puedo construir mientras el momento es favorable?"}, "12": {"k": "el estancamiento", "c": "Mantén tus principios y espera tiempos mejores.", "q": "¿Qué conviene preservar mientras nada fluye?"}, "13": {"k": "la comunidad", "c": "Busca aliados con ideales comunes y actúa a la luz.", "q": "¿Con quién comparto mis valores de verdad?"}, "14": {"k": "la abundancia", "c": "Comparte lo que tienes y conserva la humildad.", "q": "¿Cómo uso lo que tengo con generosidad?"}, "15": {"k": "la modestia", "c": "Sé humilde; equilibra y da a cada uno lo suyo.", "q": "¿Dónde me ayudaría a ser más modesto?"}, "16": {"k": "el entusiasmo", "c": "Contagia ánimo, pero planifica antes de lanzarte.", "q": "¿Mi entusiasmo tiene un plan detrás?"}, "17": {"k": "seguir al otro", "c": "Sigue lo que merece seguirse, con criterio.", "q": "¿A quién o qué sigo y por qué?"}, "18": {"k": "lo que hay que reparar", "c": "Corrige lo que se echó a perder con paciencia.", "q": "¿Qué herencia o hábito necesito reparar?"}, "19": {"k": "el acercamiento", "c": "Aprovecha el empuje que llega; no lo dejes pasar.", "q": "¿Qué se me está acercando que debo recibir?"}, "20": {"k": "la contemplación", "c": "Observa con calma antes de actuar.", "q": "¿Qué veo desde lejos que de cerca no distinguía?"}, "21": {"k": "atravesar obstáculos", "c": "Resuelve con firmeza lo que bloquea el avance.", "q": "¿Qué obstáculo necesito afrontar de una vez?"}, "22": {"k": "la gracia y la forma", "c": "Cuida la forma, pero no sacrifiques el fondo.", "q": "¿Estoy cuidando la imagen o la sustancia?"}, "23": {"k": "la desintegración", "c": "Sostente en lo esencial mientras lo viejo cae.", "q": "¿Qué estructura ya no se sostiene?"}, "24": {"k": "el retorno", "c": "Vuelve a lo esencial; un nuevo ciclo comienza.", "q": "¿A qué quiero regresar?"}, "25": {"k": "la inocencia", "c": "Actúa con naturalidad y sin segundas intenciones.", "q": "¿Qué haría si no pensara en el resultado?"}, "26": {"k": "la fuerza acumulada", "c": "Acumula experiencia y espera para actuar con peso.", "q": "¿Qué estoy acumulando que será útil?"}, "27": {"k": "la nutrición", "c": "Cuida lo que comes, lees y dices: eso te forma.", "q": "¿De qué me estoy alimentando?"}, "28": {"k": "la carga excesiva", "c": "Refuerza la base antes de seguir cargando.", "q": "¿Qué peso excede mi sostén?"}, "29": {"k": "lo abismal y el peligro", "c": "Mantén la calma y la sinceridad en la dificultad.", "q": "¿Cómo atravieso esto sin perder mi centro?"}, "30": {"k": "la claridad", "c": "Sé claro y apóyate en lo que ilumina.", "q": "¿Qué necesito ver con más luz?"}, "31": {"k": "la atracción mutua", "c": "Abre el corazón con sinceridad y sin cálculo.", "q": "¿Qué me atrae y por qué?"}, "32": {"k": "la duración", "c": "Persevera en lo que vale; la constancia crea estabilidad.", "q": "¿Qué vale la pena sostener en el tiempo?"}, "33": {"k": "la retirada", "c": "Retirarte a tiempo es sabio, no cobarde.", "q": "¿Qué conviene dejar atrás ahora?"}, "34": {"k": "el gran poder", "c": "Usa tu fuerza con justicia y sin arrogancia.", "q": "¿Mi fuerza está al servicio de lo correcto?"}, "35": {"k": "el progreso", "c": "Avanza y muéstrate; el reconocimiento llega.", "q": "¿Qué estoy listo para mostrar?"}, "36": {"k": "la luz oculta", "c": "Protege tu luz y espera sin perder la esperanza.", "q": "¿Qué parte de mí debo resguardar por ahora?"}, "37": {"k": "la familia y el clan", "c": "Cuida los roles y el afecto en casa.", "q": "¿Cómo cuido mi hogar y mis cercanos?"}, "38": {"k": "la oposición", "c": "Busca puntos en común en medio de las diferencias.", "q": "¿Qué nos une pese a lo que nos separa?"}, "39": {"k": "el obstáculo", "c": "Detente, revisa y busca ayuda de quien sabe.", "q": "¿Qué me enseña este obstáculo?"}, "40": {"k": "la liberación", "c": "Resuelve y perdona; vuelve a empezar sin cargas.", "q": "¿De qué tensión me estoy liberando?"}, "41": {"k": "la merma", "c": "Reduce lo superfluo y quédate con lo esencial.", "q": "¿A qué puedo renunciar sin perder lo importante?"}, "42": {"k": "el aumento", "c": "Aprovecha el impulso favorable y sé generoso.", "q": "¿Cómo comparto este crecimiento?"}, "43": {"k": "la irrupción decisiva", "c": "Di la verdad con firmeza, sin violencia.", "q": "¿Qué necesito aclarar de una vez?"}, "44": {"k": "el encuentro inesperado", "c": "Cuida con quién te cruzas: no todo lo que llega conviene.", "q": "¿Qué se me presenta y cómo lo evalúo?"}, "45": {"k": "la reunión", "c": "Reúnanse en torno a una meta común y a un buen líder.", "q": "¿Qué nos reúne y cómo lo cuidamos?"}, "46": {"k": "el ascenso paulatino", "c": "Sube con paciencia, paso a paso.", "q": "¿Qué paso concreto me acerca a la cima?"}, "47": {"k": "el agobio", "c": "Mantén tu integridad cuando faltan recursos.", "q": "¿Qué me sostiene cuando todo falta?"}, "48": {"k": "el pozo", "c": "Cuida la fuente que alimenta a todos y mantenla limpia.", "q": "¿Qué recurso interior necesito limpiar o profundizar?"}, "49": {"k": "la revolución", "c": "Cambia con timing y con respaldo; no por impulso.", "q": "¿Estoy listo para un cambio de fondo?"}, "50": {"k": "el caldero", "c": "Transforma lo que tienes en algo que nutra a otros.", "q": "¿Qué estoy cocinando que valga la pena compartir?"}, "51": {"k": "el trueno", "c": "Mantén la calma ante el susto: pasa y deja claridad.", "q": "¿Qué sacudida me despertó?"}, "52": {"k": "la quietud", "c": "Detente a tiempo y aquieta la mente.", "q": "¿Dónde necesito poner un alto?"}, "53": {"k": "el desarrollo gradual", "c": "Avanza sin prisa; lo sólido crece lento.", "q": "¿Respeto el ritmo natural de este proceso?"}, "54": {"k": "la unión sin base", "c": "Cuida los compromisos hechos sin madurar.", "q": "¿Esta unión tiene bases sólidas?"}, "55": {"k": "la plenitud", "c": "Disfruta del auge sin olvidar que es pasajero.", "q": "¿Cómo aprovecho mi plenitud sin aferrarme?"}, "56": {"k": "el viajero", "c": "Sé cauto y respetuoso en lo desconocido.", "q": "¿Cómo me adapto sin perder mi esencia?"}, "57": {"k": "la influencia suave", "c": "Persevera con dulzura; la suavidad penetra.", "q": "¿Dónde la suavidad logra más que la fuerza?"}, "58": {"k": "la alegría serena", "c": "Comparte la alegría y busca la conversación sincera.", "q": "¿Qué conversación me alegra y me nutre?"}, "59": {"k": "la disolución", "c": "Disuelve rigidez y rencores con apertura.", "q": "¿Qué barrera interior puedo disolver?"}, "60": {"k": "la limitación", "c": "Pon límites sanos; ni excesos ni rigidez.", "q": "¿Qué límite me conviene poner?"}, "61": {"k": "la verdad interior", "c": "Actúa desde la sinceridad; la confianza abre puertas.", "q": "¿Soy fiel a lo que siento de verdad?"}, "62": {"k": "lo pequeño que importa", "c": "Atiende los detalles, sin pretender demasiado.", "q": "¿Qué detalle merece mi atención?"}, "63": {"k": "después de la consumación", "c": "Mantén la guardia aunque todo parezca resuelto.", "q": "¿Qué puede desordenarse si me relajo?"}, "64": {"k": "antes de la consumación", "c": "Prepárate bien; falta poco para cerrar.", "q": "¿Qué me falta para llegar al final?"}};

