window.PM_SN_QTIP = function (q) {
  if (!q) return 'Consejo: escribe una pregunta concreta antes de elegir la carta; la respuesta será más precisa.';
  if (/^\s*[¿]?\s*(cu[aá]ndo|por qu[eé]|c[oó]mo|qu[eé]|qui[eé]n|d[oó]nde|cu[aá]l|cu[aá]nto)/i.test(q)) return 'Nota: el sí o no responde mejor a preguntas cerradas. Puedes reformular, por ejemplo: “¿Debería…?” o “¿Es buen momento para…?”.';
  return '';
};

