/* Portal Místico — Tarot sí o no, Runas e I Ching */
(function () {
  'use strict';
  var main = document.querySelector('[data-tool]'); if (!main) return;
  var tool = main.getAttribute('data-tool');
  var $ = function (id) { return document.getElementById(id); };
  var SITE = 'https://elportalmistico.com/juegos/';
  function rnd(n) { var a = new Uint32Array(1); (window.crypto || window.msCrypto).getRandomValues(a); return a[0] % n; }
  function shuffle(arr) { var a = arr.slice(); for (var i = a.length - 1; i > 0; i--) { var j = rnd(i + 1), t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function track(n) { if (window.gtag) try { gtag('event', n); } catch (e) {} }
  function share(text, url, btn) {
    if (navigator.share) { navigator.share({ title: document.title, text: text, url: url }).catch(function () {}); return; }
    if (navigator.clipboard) navigator.clipboard.writeText(text + ' ' + url).then(function () { btn.textContent = '✓ Copiado'; setTimeout(function () { btn.textContent = '📤 Compartir'; }, 2000); });
  }
  function scrollTo(el) { setTimeout(function () { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 60); }

  /* ====================== TAROT SÍ O NO ====================== */
  if (tool === 'tarot-sn') {
    var CARDS = window.PM_TAROT_SN, spread = $('snSpread'), out = $('caResult'), q = $('snQ');
    var ANS = {
      si: ['SÍ', 'ca-yes', ' es una carta favorable: habla de ', '. Las energías apoyan lo que preguntas; da el paso con confianza.'],
      no: ['NO', 'ca-no', ' habla de ', '. Por ahora no es el momento: conviene esperar, soltar o cambiar de enfoque.'],
      quizas: ['QUIZÁS', 'ca-maybe', ' habla de ', '. La respuesta depende de ti y de cómo actúes; vuelve a preguntar más adelante.']
    };
    function deal() {
      var deck = shuffle(CARDS).slice(0, 7);
      out.hidden = true; out.innerHTML = '';
      spread.innerHTML = deck.map(function (c, i) { return '<button type="button" class="sn-card" data-i="' + i + '" aria-label="Elegir carta ' + (i + 1) + '" style="--r:' + ((i - 3) * 6) + 'deg"><img src="tarot-game/assets/celestial-tarot-back.webp" alt="" width="120" height="191"></button>'; }).join('');
      spread.classList.remove('sn-done');
      spread.querySelectorAll('.sn-card').forEach(function (b) {
        b.addEventListener('click', function () {
          if (spread.classList.contains('sn-done')) return;
          spread.classList.add('sn-done'); b.classList.add('sn-picked');
          var c = deck[+b.getAttribute('data-i')], rev = rnd(10) < 3, key = rev ? (window.PM_SN_REV || {})[c[2]] || c[2] : c[2], A = ANS[key];
          var qtxt = q.value.trim(), dom = null; (window.PM_SN_DOMINIOS || []).concat(window.PM_SN_DOMINIOS_X || []).forEach(function (d) { if (!dom && d.re.test(qtxt)) dom = d; });
          var img = new Image(); img.src = 'tarot-game/assets/' + c[1] + '.webp';
          setTimeout(function () {
            out.innerHTML = '<div class="sn-res">' + (q.value.trim() ? '<p class="sn-q">“' + esc(q.value.trim()) + '”</p>' : '') +
              '<img class="sn-face" src="' + img.src + '" alt="' + esc(c[0]) + (rev ? ' (invertida)' : '') + '" width="220" height="351"' + (rev ? ' style="transform:rotate(180deg)"' : '') + '>' +
              '<div class="sn-ans ' + A[1] + '">' + A[0] + '</div><h2>' + esc(c[0]) + (rev ? ' <small>(invertida)</small>' : '') + '</h2>' +
              (rev ? '<p>' + esc(c[0]) + ' salió invertida y matiza la respuesta: habla de ' + c[3] + ', pero con retrasos, dudas o algo que aún no está listo. Puede que la respuesta sea “sí” o “no” solo a medias.</p>' : '<p>' + esc(c[0]) + A[2] + c[3] + A[3] + '</p>') +
              (dom ? '<p>' + dom[key] + '</p>' : '') +
              '<p class="rn-extra"><em>Siguiente paso:</em> ' + (function () { var t = (window.PM_SN_TIPS || {})[key] || []; return t.length ? t[rnd(t.length)] : ''; })() + '</p>' +
              (window.PM_SN_QTIP && window.PM_SN_QTIP(qtxt) ? '<p class="ca-note">' + window.PM_SN_QTIP(qtxt) + '</p>' : '') +
              '<div class="ca-actions"><button type="button" class="ca-btn2" id="snAgain">🔄 Hacer otra pregunta</button><button type="button" class="ca-btn2" id="caShare">📤 Compartir</button></div>' +
              '<p class="ca-more">¿Quieres una lectura más profunda? <a href="tarot.html">Haz una tirada completa de tarot →</a></p></div>';
            out.hidden = false; scrollTo(out);
            $('snAgain').addEventListener('click', function () { q.value = ''; deal(); scrollTo(main); });
            $('caShare').addEventListener('click', function () { share('El tarot me respondió ' + A[0] + ' con ' + c[0] + (rev ? ' (invertida)' : '') + '. Pregunta tú también gratis:', SITE + 'tarot-si-o-no.html', this); });
            track('tarot_si_no');
          }, 450);
        });
      });
    }
    deal();
  }

  /* ====================== RUNAS ====================== */
  if (tool === 'runas') {
    var R = window.PM_RUNAS, out2 = $('caResult');
    var RX = window.PM_RUNAS_X || {};
    function stone(r, big, rev) {
      var s = '<svg viewBox="-6 -6 52 76" class="rn-svg' + (big ? ' rn-big' : '') + '" aria-hidden="true">';
      r[2].forEach(function (l) { s += '<line x1="' + l[0] + '" y1="' + l[1] + '" x2="' + l[2] + '" y2="' + l[3] + '"/>'; });
      return '<div class="rn-stone"' + (rev ? ' style="transform:rotate(180deg)"' : '') + '>' + s + '</svg></div>';
    }
    function cast(n) {
      var pick = shuffle(R).slice(0, n).map(function (r) { var x = RX[r[0]] || {}; return { r: r, x: x, rev: !!x.i && rnd(10) < 3 }; });
      var pos = n === 1 ? ['Tu runa'] : ['Pasado', 'Presente', 'Futuro'];
      var h = '<div class="rn-row">' + pick.map(function (p, i) { return '<div class="rn-cell" style="animation-delay:' + (i * 0.25) + 's">' + stone(p.r, n === 1, p.rev) + '<div class="rn-pos">' + pos[i] + '</div><div class="rn-name">' + p.r[0] + (p.rev ? ' <small>(invertida)</small>' : '') + '</div></div>'; }).join('') + '</div>';
      h += '<div class="ca-list">' + pick.map(function (p, i) {
        var r = p.r, x = p.x, t = '<div class="ca-item"><div class="ca-item-t">' + (n > 1 ? pos[i] + ': ' : '') + r[0] + (p.rev ? ' invertida' : '') + ' <small>(' + r[1] + ')</small></div>';
        if (p.rev) t += '<p>' + x.i + ' <strong>' + r[4] + '</strong></p>';
        else { t += '<p>' + r[3] + ' <strong>' + r[4] + '</strong></p>'; if (x.a) t += '<p class="rn-extra"><em>En el amor:</em> ' + x.a.replace(/^En el amor,?\s*/, '') + '</p><p class="rn-extra"><em>En el trabajo:</em> ' + x.t.replace(/^En el trabajo( y el dinero)?,?\s*/, '') + '</p>'; }
        var x2 = (window.PM_RUNAS_X2 || {})[r[0]];
        if (x2) {
          if (n > 1 && i === 0 && !p.rev) t += '<p class="rn-extra"><em>Como pasado:</em> ' + x2.p.charAt(0).toUpperCase() + x2.p.slice(1) + '.</p>';
          if (n > 1 && i === 2 && !p.rev) t += '<p class="rn-extra"><em>Como futuro:</em> ' + x2.f.charAt(0).toUpperCase() + x2.f.slice(1) + '.</p>';
          t += '<p class="rn-extra"><em>' + (p.rev ? 'Cómo manejarlo:' : 'Consejo práctico:') + '</em> ' + (p.rev ? x2.ic : x2.c) + '</p>';
          t += '<p class="rn-extra"><em>Para reflexionar:</em> ' + x2.q + '</p>';
          if (!p.rev) t += '<p class="rn-extra"><em>Afirmación:</em> “' + x2.af + '”</p>';
        }
        return t + '</div>';
      }).join('') + '</div>';
      if (n === 3 && pick[0].x.k) {
        var inv = pick.filter(function (p) { return p.rev; }).length;
        h += '<p class="ca-note" style="text-align:center">Tu tirada va de ' + pick[0].x.k + ' (pasado) a ' + pick[1].x.k + ' (presente), y apunta hacia ' + pick[2].x.k + ' (futuro).' + (inv ? ' Las runas invertidas señalan donde conviene ir más despacio o revisar.' : '') + '</p>';
      }
      h += '<div class="ca-actions"><button type="button" class="ca-btn2" id="rnAgain">🔄 Volver a tirar</button><button type="button" class="ca-btn2" id="caShare">📤 Compartir</button></div>';
      out2.innerHTML = h; out2.hidden = false; scrollTo(out2);
      $('rnAgain').addEventListener('click', function () { cast(n); });
      $('caShare').addEventListener('click', function () { share('Mis runas: ' + pick.map(function (p) { return p.r[0] + (p.rev ? ' (invertida)' : ''); }).join(', ') + '. Haz tu tirada de runas gratis:', SITE + 'runas.html', this); });
      track('runas_tirada');
    }
    $('rn1').addEventListener('click', function () { cast(1); });
    $('rn3').addEventListener('click', function () { cast(3); });
  }

  /* ====================== I CHING ====================== */
  if (tool === 'iching') {
    var I = window.PM_ICHING, out3 = $('caResult'), lines = [], board = $('icBoard');
    function hexOf(bits) {
      var lo = bits.slice(0, 3).join(''), up = bits.slice(3, 6).join('');
      return { n: I.table[I.order.indexOf(lo)][I.order.indexOf(up)], lo: I.trig[lo], up: I.trig[up] };
    }
    function drawHex(bits, moving) {
      var s = '<svg viewBox="0 0 120 132" class="ic-hex" aria-hidden="true">';
      for (var i = 0; i < 6; i++) {
        var y = 116 - i * 22, mv = moving && moving[i], col = mv ? '#F08A8C' : '#E9D9A6';
        if (bits[i]) s += '<rect x="6" y="' + y + '" width="108" height="12" rx="2" fill="' + col + '"/>';
        else s += '<rect x="6" y="' + y + '" width="46" height="12" rx="2" fill="' + col + '"/><rect x="68" y="' + y + '" width="46" height="12" rx="2" fill="' + col + '"/>';
      }
      return s + '</svg>';
    }
    function renderBoard() {
      var s = '<svg viewBox="0 0 120 132" class="ic-hex" aria-hidden="true">';
      for (var i = 0; i < 6; i++) {
        var y = 116 - i * 22, v = lines[i];
        if (v === undefined) { s += '<rect x="6" y="' + y + '" width="108" height="12" rx="2" fill="none" stroke="rgba(233,217,166,0.25)" stroke-dasharray="4 4"/>'; continue; }
        var col = (v === 6 || v === 9) ? '#F08A8C' : '#E9D9A6';
        s += (v === 7 || v === 9) ? '<rect x="6" y="' + y + '" width="108" height="12" rx="2" fill="' + col + '"/>' : '<rect x="6" y="' + y + '" width="46" height="12" rx="2" fill="' + col + '"/><rect x="68" y="' + y + '" width="46" height="12" rx="2" fill="' + col + '"/>';
      }
      board.innerHTML = s + '</svg>';
      $('icCount').textContent = lines.length + ' de 6 líneas';
      $('icToss').textContent = lines.length < 6 ? '🪙 Lanzar las monedas (' + (lines.length + 1) + '/6)' : '✓ Hexagrama completo';
      $('icToss').disabled = lines.length >= 6;
    }
    function toss() {
      if (lines.length >= 6) return;
      var coins = [rnd(2), rnd(2), rnd(2)], v = coins.reduce(function (s, c) { return s + (c ? 3 : 2); }, 0);
      $('icCoins').innerHTML = coins.map(function (c) { return '<span class="ic-coin ' + (c ? 'ic-h' : 'ic-t') + '">' + (c ? 'Cara' : 'Cruz') + '</span>'; }).join('');
      lines.push(v); renderBoard();
      if (lines.length === 6) result();
    }
    function result() {
      var bits = lines.map(function (v) { return v === 7 || v === 9 ? 1 : 0; }), mv = lines.map(function (v) { return v === 6 || v === 9; });
      var H = hexOf(bits), N = I.names[H.n], movIdx = [];
      mv.forEach(function (m, i) { if (m) movIdx.push(i + 1); });
      var h = '<div class="ic-res">' + (($('icQ').value || '').trim() ? '<p class="sn-q">“' + esc($('icQ').value.trim()) + '”</p>' : '') + drawHex(bits, mv) +
        '<div class="ca-kick">Hexagrama ' + H.n + '</div><h2>' + N[0] + '</h2><p class="ic-tri">' + H.up[1] + ' sobre ' + H.lo[1] + '</p><p>' + N[1] + '</p></div>';
      var X = (window.PM_ICHING_X || [])[H.n], TA = window.PM_TRIG_ATTR || {};
      if (X) {
        h += '<div class="ca-item"><div class="ca-item-t">Qué dice el hexagrama</div><p>' + X[0] + '</p><p class="rn-extra">Arriba, ' + H.up[1] + ' (' + (TA[H.up[1]] || '') + '); abajo, ' + H.lo[1] + ' (' + (TA[H.lo[1]] || '') + '). Su combinación define el carácter de la situación.</p></div>';
        h += '<div class="ca-item"><div class="ca-item-t">En el amor</div><p>' + X[1].replace(/^En el amor,?\s*/, '').replace(/^./, function (c) { return c.toUpperCase(); }) + '</p></div>';
        h += '<div class="ca-item"><div class="ca-item-t">En el trabajo</div><p>' + X[2].replace(/^En el trabajo,?\s*/, '').replace(/^./, function (c) { return c.toUpperCase(); }) + '</p></div>';
      }
      var XX = (window.PM_ICHING_X2 || {})[H.n];
      if (XX) h += '<div class="ca-item"><div class="ca-item-t">Tema y consejo</div><p>El tema central es <strong>' + XX.k + '</strong>. ' + XX.c + '</p><p class="rn-extra"><em>Para reflexionar:</em> ' + XX.q + '</p></div>';
      if (movIdx.length) {
        var bits2 = bits.map(function (b, i) { return mv[i] ? 1 - b : b; }), H2 = hexOf(bits2), N2 = I.names[H2.n];
        h += '<div class="ca-item"><div class="ca-item-t">Líneas que cambian: ' + movIdx.join(', ') + '</div><p>Las líneas en rojo están en movimiento: la situación se transforma.</p>' + movIdx.map(function (i) { var X2 = (window.PM_ICHING_X2 || {})[H.n], LT = (window.PM_ICHING_LINE_TXT || {})[i]; var yang = lines[i - 1] === 9; return '<p class="rn-extra">' + (X2 && LT ? LT[yang ? 9 : 6].replace('{k}', X2.k).replace(/tema de (el|los) /,function (m, a) { return a === 'el' ? 'tema del ' : 'tema de los '; }) : ((window.PM_ICHING_LINES || [])[i] || '')) + '</p>'; }).join('') + '<p>Hacia dónde va:</p></div>';
        h += '<div class="ic-res ic-res2">' + drawHex(bits2) + '<div class="ca-kick">Se transforma en el hexagrama ' + H2.n + '</div><h2>' + N2[0] + '</h2><p>' + N2[1] + '</p>' + (((window.PM_ICHING_X || [])[H2.n]) ? '<p class="rn-extra">' + window.PM_ICHING_X[H2.n][0] + '</p>' : '') + '</div>';
      } else h += '<p class="ca-note" style="text-align:center">Ninguna línea cambia: la situación es estable y el consejo se aplica tal cual.</p>';
      h += '<div class="ca-actions"><button type="button" class="ca-btn2" id="icAgain">🔄 Nueva consulta</button><button type="button" class="ca-btn2" id="caShare">📤 Compartir</button></div>';
      out3.innerHTML = h; out3.hidden = false; scrollTo(out3);
      $('icAgain').addEventListener('click', function () { lines = []; $('icCoins').innerHTML = ''; out3.hidden = true; renderBoard(); $('icQ').value = ''; scrollTo(main); });
      $('caShare').addEventListener('click', function () { share('El I Ching me dio el hexagrama ' + H.n + ': ' + N[0] + '. Consulta el tuyo gratis:', SITE + 'i-ching.html', this); });
      track('iching_consulta');
    }
    $('icToss').addEventListener('click', toss);
    $('icAll').addEventListener('click', function () { while (lines.length < 6) toss(); });
    renderBoard();
  }
  /* ====================== ÁNGEL DE LA GUARDA ====================== */
  if (tool === 'angel') {
    var AN = window.PM_ANGELES, out4 = $('caResult');
    var CHOIRS = ['Serafines', 'Querubines', 'Tronos', 'Dominaciones', 'Potencias', 'Virtudes', 'Principados', 'Arcángeles', 'Ángeles'];
    var MES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
    function k(m, d) { return m * 100 + d; }
    function find(m, d) {
      for (var i = 0; i < AN.length; i++) { var s = k(AN[i][1][0], AN[i][1][1]), e = k(AN[i][2][0], AN[i][2][1]), x = k(m, d); if (s <= e ? (x >= s && x <= e) : (x >= s || x <= e)) return i; }
      return 0;
    }
    try { var sv = JSON.parse(localStorage.getItem('pmCarta') || 'null'); if (sv && sv.date) $('agDate').value = sv.date; } catch (e) {}
    $('caForm').addEventListener('submit', function (e) {
      e.preventDefault(); $('caError').textContent = '';
      var v = $('agDate').value; if (!v) { $('caError').textContent = 'Escribe tu fecha de nacimiento.'; return; }
      var p = v.split('-').map(Number), i = find(p[1], p[2]), A = AN[i], num = ((i - 16 + 72) % 72) + 1, choir = CHOIRS[Math.floor((num - 1) / 8)];
      var range = A[1][1] + ' de ' + MES[A[1][0] - 1] + ' al ' + A[2][1] + ' de ' + MES[A[2][0] - 1];
      var h = '<div class="ag-res"><div class="ag-halo">👼</div><div class="ca-kick">Tu ángel de la guarda es</div><h2>' + A[0] + '</h2>' +
        '<div class="ca-pills"><span>Ángel nº ' + num + ' de 72</span><span>Coro de los ' + choir + '</span>' + (window.PM_ANGEL_REFS ? '<span>' + window.PM_ANGEL_REFS[num - 1] + '</span>' : '') + '<span>' + range + '</span></div>' +
        '<p class="ag-txt">' + A[0] + ' ' + A[3] + '.</p></div>' +
        '<div class="ca-list"><div class="ca-item"><div class="ca-item-t">Cómo conectar con ' + A[0] + '</div><p>Busca un momento tranquilo, enciende una vela blanca si lo deseas y repite su nombre en voz baja tres veces. Después, cuéntale con tus palabras qué necesitas. Muchas personas lo hacen en los días de su periodo (del ' + range + ') y el día de su cumpleaños.</p></div>' +
        '<div class="ca-item"><div class="ca-item-t">Una oración sencilla</div><p class="ag-pray">“' + A[0] + ', ángel de mi guarda, gracias por acompañarme. Ayúdame hoy a ver con claridad, a actuar con amor y a reconocer tus señales en mi camino. Así sea.”</p></div></div>' +
        '<div class="ca-actions"><button type="button" class="ca-btn2" id="caShare">📤 Compartir</button></div>' +
        '<p class="ca-more">¿Ves números repetidos como 111 o 444? Lee qué significan los <a href="../blog/numeros-angelicales-significado.html">números angelicales →</a></p>';
      out4.innerHTML = h; out4.hidden = false; scrollTo(out4);
      $('caShare').addEventListener('click', function () { share('Mi ángel de la guarda es ' + A[0] + '. Descubre el tuyo gratis:', SITE + 'angel-de-la-guarda.html', this); });
      track('angel_guarda');
    });
  }
})();
;
